# participant-config.yaml
apiVersion: v1
kind: ConfigMap
metadata:
  name: fate-participant-config
  namespace: fate-cluster
data:
  party.conf: |
    {
      \"local\": {
        \"party_id\": 10000,
        \"role\": \"guest\"
      },
      \"partners\": [
        {
          \"party_id\": 9999,
          \"role\": \"host\",
          \"ip\": \"partner-host.company.com\",
          \"port\": 9380,
          \"secure_protocol\": \"https\"
        },
        {
          \"party_id\": 9998,
          \"role\": \"arbiter\",
          \"ip\": \"arbiter.company.com\",
          \"port\": 9380,
          \"secure_protocol\": \"https\"
        }
      ],
      \"communication\": {
        \"proxy\": \"nginx\",
        \"ssl_enabled\": true,
        \"cert_path\": \"/etc/fate/certs\",
        \"timeout\": 300
      },
      \"security\": {
        \"encrypt_type\": \"paillier\",
        \"key_length\": 1024,
        \"diffie_hellman\": {
          \"enabled\": true,
          \"group\": \"MODP_2048\"
        }
      }
    }

  algorithm.conf: |
    {
      \"algorithm\": \"hetero_lr\",
      \"initiator\": {
        \"role\": \"guest\",
        \"party_id\": 10000
      },
      \"job_parameters\": {
        \"work_mode\": 1,
        \"model_id\": \"hetero_logistic_regression_001\",
        \"model_version\": \"20260205\"
      },
      \"role_parameters\": {
        \"guest\": {
          \"args\": {
            \"data\": {
              \"train_data\": [{\"name\": \"guest_train_data\", \"namespace\": \"experiment\"}]
            }
          },
          \"dataio_0\": {
            \"with_label\": true,
            \"label_name\": \"y\",
            \"label_type\": \"int\"
          }
        },
        \"host\": {
          \"args\": {
            \"data\": {
              \"train_data\": [{\"name\": \"host_train_data\", \"namespace\": \"experiment\"}]
            }
          },
          \"dataio_0\": {
            \"with_label\": false
          }
        }
      },
      \"component_parameters\": {
        \"common\": {
          \"hetero_lr_0\": {
            \"penalty\": \"L2\",
            \"optimizer\": \"sgd\",
            \"alpha\": 0.01,
            \"max_iter\": 30,
            \"batch_size\": 500,
            \"learning_rate\": 0.15,
            \"decay\": 1,
            \"decay_sqrt\": true,
            \"init_param\": {
              \"init_method\": \"random_uniform\"
            }
          }
        }
      }
    }
